import numpy as np

def extract_features(image: np.ndarray) -> np.ndarray:
    image = np.asarray(image, dtype=float)
    h, w = image.shape

    # Feature 1: Global intensity mean
    f1 = np.mean(image)

    # Feature 2: Pixel-wise intensity co-occurrence (mean absolute difference with shifted image)
    shift = 3
    if w > shift:
        co_occur = np.mean(np.abs(image[:, shift:] - image[:, :-shift]))
    else:
        co_occur = 0.0
    f2 = co_occur

    # Feature 3: Horizontal profile asymmetry (left vs right mean difference normalized)
    half = w // 2
    if half > 0:
        left_mean = np.mean(image[:, :half])
        right_mean = np.mean(image[:, half:])
    else:
        left_mean = right_mean = 0.0
    f3 = (left_mean - right_mean) / (np.mean(image) + 1e-6)

    # Feature 4: Row-wise intensity variation (mean of per-row standard deviations)
    if h > 1:
        row_std = np.std(image, axis=1)
        f4 = np.mean(row_std)
    else:
        f4 = 0.0

    # Feature 5: Column-wise intensity variation (mean of per-column standard deviations)
    if w > 1:
        col_std = np.std(image, axis=0)
        f5 = np.mean(col_std)
    else:
        f5 = 0.0

    # Feature 6: Auto-correlation at lag 1 along rows (mean of row-wise correlation)
    if w > 1:
        row_corr = []
        for r in range(h):
            row = image[r, :]
            row_std_local = np.std(row)
            if row_std_local > 1e-6:
                corr = np.mean((row[:-1] - np.mean(row[:-1])) * (row[1:] - np.mean(row[1:]))) / (row_std_local ** 2)
                row_corr.append(corr)
            else:
                row_corr.append(0.0)
        f6 = np.mean(row_corr)
    else:
        f6 = 0.0

    # Feature 7: Number of local intensity transitions (proportion of pixels where value changes sign of gradient along rows)
    if w > 1:
        diff_sign = np.sign(np.diff(image, axis=1))
        transitions = np.mean(np.abs(diff_sign[:, 1:] - diff_sign[:, :-1])) / 2.0
        f7 = transitions
    else:
        f7 = 0.0

    # Feature 8: Energy of intensity (mean squared value normalized by mean)
    mean_val = np.mean(image)
    if mean_val > 1e-6:
        f8 = np.mean(image ** 2) / (mean_val ** 2)
    else:
        f8 = 0.0

    return np.array([f1, f2, f3, f4, f5, f6, f7, f8], dtype=float)
